head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF30627.xml";
scwin.gLastJob = "";

//자료수정 시 부모창으로부터 넘어온 데이터
scwin.key_edu_partc_id = frame.opener.scwin.key_edu_partc_id; //PK
scwin.key_isur_cd = frame.opener.scwin.key_isur_cd; //회사코드
scwin.key_chrg_tp_cd = frame.opener.scwin.key_chrg_tp_cd; //담당자구분코드
scwin.key_edu_id = frame.opener.scwin.key_edu_id; //교육일정코드
scwin.key_chrg_nm = frame.opener.scwin.key_chrg_nm; // 선택된참가자명
scwin.key_edu_nm = frame.opener.scwin.key_edu_nm; // 선택과정명
scwin.key_edu_ack_tm = frame.opener.scwin.key_edu_ack_tm;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 이수시간


// 대상년도 초기화
scwin.fn_Init = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "^전체";
    for (var i = yyyy; i >= 2010; i--) {
        str += "," + i + "%^" + i;
    }

    //값 초기화
    tbx_COM_NM.setValue("");
    tbx_CHRG_TP_NM.setValue("");
    tbx_CHRG_NM.setValue("");
    tbx_hidden_chrg_tp_cd.setValue("");
    tbx_ASIS_DUTY_EDU_TM.setValue("");
    tbx_ASIS_EDU_ACK_TM.setValue("");
    tbx_TOBE_DUTY_EDU_TM.setValue("");
    tbx_TOBE_EDU_ACK_TM.setValue("");
    tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.setValue("");
    $c.stf.showObj(tbx_hidden_chrg_tp_cd, false);
    $c.stf.showObj(tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD, false);
};



//담당자 검색
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=listDisclsEduNattend2";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&CHRG_NM=" + $c.stf.getObjectValue(txb_chrg_nm);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_ComDisclsPerson.DataID = encodeURI(url);
    dts_ComDisclsPerson.Reset();
};



//선택한 담당자에 대한 이력변경 대상 목록 조회(회사코드, 담당자명, 담당자구분코드)
scwin.fn_Search2 = function(p_isur_cd, p_chrg_nm, p_chrg_tp_cd) {
    $c.cm.ShowWin(grd_Grid2);
    var url = "/ListedCompany.do?method=listDisclsEduHistory";
    url += "&ISUR_CD=" + p_isur_cd;
    url += "&CHRG_NM=" + p_chrg_nm;
    url += "&CHRG_TP_CD=" + p_chrg_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Edu_Plan.DataID = encodeURI(url);
    dts_Edu_Plan.Reset();
};



//저장
scwin.fn_Save = function() {
    if (tbx_COM_NM.getValue() == '' || tbx_hidden_chrg_tp_cd.getValue() == '') {
        $c.win.alert('이력변경 대상자를 선택하시기 바랍니다.');
        return;
    }
    if (dts_Edu_Plan.getTotalRow() == 0) {
        $c.win.alert('변경가능한 교육참가이력이 없습니다.');
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        for (var i = 1; i <= dts_Edu_Plan.getTotalRow(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(i, "EDU_PARTC_ID", dts_Edu_Plan.getCellData(i, "EDU_PARTC_ID"));
        }
        var url = "/ListedCompany.do?method=saveDisclsEduPartcHistory";
        url += "&CHRG_TP_CD=" + tbx_hidden_chrg_tp_cd.getValue();
        url += "&DISCLS_BZ_CHRG_ASSGN_DD=" + tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.getValue();
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
        trs_Save.Post();
    }
};
scwin.fn_setHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ISSUEINFO_DISCLS_EDU_PARTC_HISTORY_INOUT";
    dts_Save.Reset();
};
scwin.dts_ComDisclsPerson_OnFail = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadError = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_ComDisclsPerson.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.grd_Grid_OnClick = function(row, colid) {
    //선택값 셋팅
    var CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); //담당자명
    var COM_ABBRV = dts_ComDisclsPerson.getCellData(row, "COM_ABBRV"); //회사명
    var EDU_KIND_NM = dts_ComDisclsPerson.getCellData(row, "EDU_KIND_NM"); //담당자구분	 
    var CHRG_TP_CD = dts_ComDisclsPerson.getCellData(row, "CHRG_TP_CD"); //담당자구분코드	 
    var DISCLS_BZ_CHRG_ASSGN_DD = dts_ComDisclsPerson.getCellData(row, "DISCLS_BZ_CHRG_ASSGN_DD"); //담당자지정일

    tbx_COM_NM.setValue(COM_ABBRV);
    tbx_CHRG_TP_NM.setValue(EDU_KIND_NM);
    tbx_CHRG_NM.setValue(CHAR_NM);
    tbx_hidden_chrg_tp_cd.setValue(CHRG_TP_CD);
    tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.setValue(DISCLS_BZ_CHRG_ASSGN_DD);


    //두번째 그리드 조회(변경이력 내역 조회)
    var ISUR_CD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); //회사코드
    scwin.fn_Search2(ISUR_CD, CHAR_NM, CHRG_TP_CD);


    // '교육참가이력 변경적용 시물레이션 결과' 값 셋팅
    tbx_ASIS_DUTY_EDU_TM.setValue(dts_ComDisclsPerson.getCellData(row, "DUTY_EDU_TM")); //교육의무시간(변경전)
    tbx_ASIS_EDU_ACK_TM.setValue(dts_ComDisclsPerson.getCellData(row, "EDU_ACK_TM")); //이수시간(변경전)
    tbx_TOBE_DUTY_EDU_TM.setValue(dts_ComDisclsPerson.getCellData(row, "DUTY_EDU_TM")); //교육의무시간(변경후)

};
scwin.grd_Grid_OnDblClick = function(row, colid) {

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_chrg_nm_onkeypress = function() {
    scwin.fn_Search(); //엔터키 입력시 조회 수행

};
scwin.dts_Edu_Plan_OnFail = function() {
    $c.stf.alert_error(dts_Edu_Plan);
    $c.cm.CloseWin('', grd_Grid2);
};
scwin.dts_Edu_Plan_OnLoadError = function() {
    $c.stf.alert_error(dts_Edu_Plan);
    $c.cm.CloseWin('', grd_Grid2);
};
scwin.dts_Edu_Plan_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_Edu_Plan.removeAll();
        tbx_TOBE_DUTY_EDU_TM.setValue("");
        tbx_TOBE_EDU_ACK_TM.setValue("");
    } else {
        //변경후 이수시간 계산 및 값 입력
        var EDU_ACK_TM_SUM = 0;
        for (var i = 1; i <= rowcount; i++) {
            EDU_ACK_TM_SUM = parseInt(EDU_ACK_TM_SUM) + parseInt(dts_Edu_Plan.getCellData(i, "EDU_ACK_TM"));
        }
        tbx_TOBE_EDU_ACK_TM.setValue(EDU_ACK_TM_SUM); //이수시간(변경후)

    }
    $c.cm.CloseWin(rowcount, grd_Grid2); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("Error Code : " + trs_Save.ErrorCode + "\n" + "Error Message : " + trs_Save.ErrorMsg + "\n");
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    scwin.fn_setHeader();
};
